        running_tasks[task] = {'machine': machine, 'start_time': time, 'run_time': run_time, 'priority': priority, 'cpu': cpu, 'memory': memory}
    elif event == 'finish':
        if task in running_tasks:
            del running_tasks[task]
    elif event == 'evict':
