# Let me write a simulation to compare the two scenarios
# I'll implement the scheduling policy step by step

def simulate(machines_config, submissions, m05_fails=True):
    """
    Simulate the scheduling and return first_start times for each task
    """
    # Deep copy machines
    machines = {}
    for mid, info in machines_config.items():
        machines[mid] = {
            'CPU_used': 0,
            'mem_used': 0,
            'CPU_total': info['CPU'],
            'mem_total': info['memory'],
            'is_up': True,
            'running': []  # list of (task_id, start_time, end_time)
        }

    # Track task states
    task_info = {}  # task_id -> {priority, CPU, memory, run_time, submit_time, first_start}
    task_running = {}  # task_id -> {machine, start_time, end_time}

    # Initialize task_info from submissions
    for t in submissions:
        task_info[t['task']] = {
            'priority': t['priority'],
            'CPU': t['CPU'],
            'memory': t['memory'],
            'run_time': t['run_time'],
            'submit_time': t['time'],
            'first_start': None
        }

    # Queue of waiting tasks (just task_ids)
    queue = []
    # Track task status: 'submitted', 'queued', 'running', 'finished', 'evicted'
    status = {}
    for t in submissions:
        status[t['task']] = None  # not yet submitted

    # Collect all event times
    event_times = set([0])
    for t in submissions:
        event_times.add(t['time'])
    for mid, info in machines_config.items():
        if info['fails_at'] is not None and (m05_fails or mid != 'M05'):
            event_times.add(info['fails_at'])
        if info['returns_at'] is not None:
            event_times.add(info['returns_at'])
    # Also need times when running tasks finish
    # We'll iterate and collect as we go

    event_times = sorted(event_times)

    # We need to track running task end times for future events
    running_end_times = set()

    for current_time in event_times:
        # 1. Finishes
        finished_tasks = []
        for mid in sorted(machines.keys()):
            m = machines[mid]
            if m['is_up']:
                new_running = []
                for (tid, start, end) in m['running']:
                    if end <= current_time:
                        finished_tasks.append((mid, tid, start, end))
                    else:
                        new_running.append((tid, start, end))
                        running_end_times.add(end)
                m['running'] = new_running

        # Update machine usage after finishes
        # Recalculate usage from running tasks
        for mid in machines:
            m = machines[mid]
            m['CPU_used'] = sum(task_info[tid]['CPU'] for tid, _, _ in m['running'])
            m['mem_used'] = sum(task_info[tid]['memory'] for tid, _, _ in m['running'])

        for (mid, tid, start, end) in finished_tasks:
            status[tid] = 'finished'
            del task_running[tid]

        # Add new end times to event_times
        for et in list(running_end_times):
            if et > current_time:
                event_times_set = set(event_times)
                event_times_set.add(et)
                event_times = sorted(event_times_set)

        # 2. Failures
        for mid in sorted(machines.keys()):
            m = machines[mid]
            fail_time = machines_config[mid]['fails_at']
            if mid == 'M05' and not m05_fails:
                fail_time = None  # Skip M05 failure
            if m['is_up'] and fail_time == current_time:
                m['is_up'] = False
                evicted_from_fail = []
                for (tid, start, end) in list(m['running']):
                    evicted_from_fail.append((tid, start, end))
                    # Task goes back to queue
                    queue.append(tid)
                    status[tid] = 'queued'
                    del task_running[tid]
